use serde_json::{json,Value};use sha2::{Digest,Sha256};
use std::{fs,path::{Path,PathBuf},collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/query-wrapper176";const Z:&str="/home/ubuntu/src/zk-tools/zopro";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn receipt(p:&Path){let e=read(p.join("exit.json"));assert_eq!(e["returncode"],0,"{}",p.display());assert_eq!(e["success"],true);for s in["stdout","stderr"]{assert_eq!(hash(p.join(format!("{s}.log"))),e[format!("{s}_sha256")].as_str().unwrap());}}
fn expected(step:&Value)->Value{let mut a=vec![json!("timeout"),json!("-k"),json!("5s"),json!(format!("{}s",step["timeout_seconds"].as_u64().unwrap()))];a.extend(step["argv"].as_array().unwrap().iter().cloned());json!(a)}
fn stat(v:&[f64])->Value{assert_eq!(v.len(),15);let mut s=v.to_vec();s.sort_by(f64::total_cmp);json!({"median":s[7],"lower":s[3],"upper":s[11],"wins":v.iter().filter(|&&x|x<1.).count(),"values":v})}
fn same(a:&Value,b:&Value){for k in["median","lower","upper"]{let x=a[k].as_f64().unwrap();let y=b[k].as_f64().unwrap();assert!((x-y).abs()<=x.abs().max(y.abs()).max(1.)*1e-12);}assert_eq!(a["wins"],b["wins"]);}
fn main(){let mut pins=0;for n in["build-pins.json","consumer-pins.json","capture-pins.json"]{for(p,h)in read(r(n)).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap(),"{p}");pins+=1;}}
 let audit=read(r("source-audit.json"));let manifest=read(Path::new(Z).join("docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json"));let mut exact=0;for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new(Z).join(p)),h.as_str().unwrap());let path=r("source").join(p);assert_eq!(hash(&path),audit["source_sha256"][p]);let bytes=fs::read(&path).unwrap();if hash(&path)==h.as_str().unwrap(){exact+=1;}else{assert_eq!(p,"crates/zopro-core/src/lib.rs");let s=String::from_utf8(bytes).unwrap();assert_eq!(s.strip_suffix(audit["export_suffix"].as_str().unwrap()).unwrap().as_bytes(),fs::read(Path::new(Z).join(p)).unwrap());}}assert_eq!(exact,175);
 let mut commands=0;for(plan,out)in[("native-plan.json","native"),("consumer-plan.json","consumers"),("capture-plan.json","runs")]{assert_eq!(read(r(format!("{out}/result.json")))["status"],"complete");for step in read(r(plan))["steps"].as_array().unwrap(){let p=r(out).join(step["name"].as_str().unwrap());receipt(&p);let c=read(p.join("command.json"));if step["kind"]=="command"{assert_eq!(c["argv"],expected(step));}else{let a=c["argv"].as_array().unwrap();assert!(a.iter().any(|x|x=="-O"));for f in["target-cpu=native","lto=fat","codegen-units=1"]{assert!(a.windows(2).any(|w|w[0]=="-C"&&w[1]==f));}}commands+=1;}}
 let tests=fs::read_to_string(r("native/full-core-candidate/stdout.log")).unwrap();assert!(tests.contains("test result: ok. 126 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out"));assert!(tests.contains("direct_and_tls_entries_match_generator_on_small_stack_pools ... ok"));
 let ids=read(r("identities.json"));assert_eq!(ids["TLS"],ids["DIRECT"]);for label in["FROZEN","KNOWN_FRESH","TLS","DIRECT"]{let p=ids[label]["binary"].as_str().unwrap();assert_eq!(hash(p),ids[label]["binary_sha256"].as_str().unwrap());}
 let a=read(r("analysis.json"));let jobs=read(r("jobs.json"));let mut data=BTreeMap::<(String,String,usize),Value>::new();let mut rows=BTreeMap::new();let mut reused=0;let mut queries=0;
 for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let p=j["reused_from"].as_str().map(PathBuf::from).unwrap_or_else(||r("runs").join(name));if j["reused_from"].is_string(){reused+=1;}receipt(&p);assert_eq!(read(p.join("command.json"))["argv"],expected(&j["command"]));let text=fs::read_to_string(p.join("stdout.log")).unwrap();let x:Value=serde_json::from_str(text.lines().find_map(|l|l.strip_prefix("CALLER ")).unwrap()).unwrap();assert_eq!(x["query"],j["actual_query"]);assert_eq!(x["workers"],j["case"]["workers"]);assert_eq!(x["rounds"],j["rounds"]);assert_eq!(x["metadata"]["route"],0);assert_eq!(x["metadata"]["retained_payload_bytes"],0);for k in["all_timed_outputs_checked","every_output_matches_independent_full_MSM","point_inputs_unchanged","normalization_inside_timer"]{assert_eq!(x[k],true);}assert_eq!(x["B_word_reset_inside_timer"],j["case"]["query"]=="B");queries+=j["rounds"].as_u64().unwrap()+4;for w in x["worker_rows"].as_array().unwrap(){assert_eq!(w["cpu"].as_u64().unwrap(),if x["workers"]==1{2}else{w["worker"].as_u64().unwrap()});}if j["panel"]=="latency"{assert!(data.insert((j["case"]["name"].as_str().unwrap().into(),j["variant"].as_str().unwrap().into(),j["block"].as_u64().unwrap()as usize),x.clone()).is_none());}rows.insert(name.to_string(),x);}
 assert_eq!(reused,14);assert_eq!(data.len(),420);assert_eq!(rows.len(),464);let mut cells=BTreeMap::new();for c in read(r("cases.json")).as_array().unwrap(){let name=c["name"].as_str().unwrap();let mut times=BTreeMap::new();for label in["FROZEN","KNOWN_FRESH","TLS","DIRECT"]{let v=(0..15).map(|b|{let x=&data[&(name.into(),label.into(),b)];let mut s=x["samples_ns"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()).collect::<Vec<_>>();assert_eq!(s.len(),17);s.sort();s[8]as f64}).collect::<Vec<_>>();same(&stat(&v),&a["cases"][name]["timings_ns"][label]);let peak=(0..15).map(|b|data[&(name.into(),label.into(),b)]["usage"]["whole_process_maxrss_kib"].as_f64().unwrap()/1024.).fold(0f64,f64::max);assert_eq!(peak,a["cases"][name]["maxRSS_MiB"][label].as_f64().unwrap());times.insert(label,v);}
  let mut comps=BTreeMap::new();for(n,d)in[("DIRECT","TLS"),("TLS","DIRECT"),("DIRECT","KNOWN_FRESH"),("TLS","KNOWN_FRESH"),("KNOWN_FRESH","FROZEN"),("DIRECT","FROZEN"),("TLS","FROZEN")]{let s=stat(&times[n].iter().zip(&times[d]).map(|(x,y)|x/y).collect::<Vec<_>>());same(&s,&a["cases"][name]["comparisons"][format!("{n}_over_{d}")]);comps.insert(format!("{n}_over_{d}"),s);}cells.insert(name.to_string(),comps);
 }
 let mut explanatory=true;let mut equivalent=true;for name in["1x2-B-w32","2x2-B-w32"]{let c=&cells[name];let tls=&c["TLS_over_DIRECT"];let df=&c["DIRECT_over_KNOWN_FRESH"];let dt=&c["DIRECT_over_TLS"];explanatory&=tls["upper"].as_f64().unwrap()<1.&&tls["wins"].as_u64().unwrap()>=10&&df["lower"].as_f64().unwrap()>1.&&df["median"].as_f64().unwrap()>=1.03;equivalent&=dt["lower"].as_f64().unwrap()>=1./1.02&&dt["upper"].as_f64().unwrap()<=1.02;}assert_eq!(a["wrapper_reproduces_material_prior_gap"],explanatory);assert_eq!(a["DIRECT_TLS_intervals_within_two_percent"],equivalent);
 let mut samples=0;for j in jobs.as_array().unwrap().iter().filter(|j|j["panel"]=="cycles"){let name=j["name"].as_str().unwrap();let x=&rows[name];let pid=x["pid"].as_u64().unwrap();let allowed=x["worker_rows"].as_array().unwrap().iter().map(|w|(w["tid"].as_u64().unwrap(),w["cpu"].as_u64().unwrap())).collect::<BTreeMap<_,_>>();let mut count=0;for l in fs::read_to_string(r(format!("runs/decode-{name}/stdout.log"))).unwrap().lines(){let l=l.trim();if l.is_empty()||l.starts_with('#'){continue;}let f=l.split_whitespace().collect::<Vec<_>>();let(p,t)=f[0].split_once('/').unwrap();assert_eq!(p.parse::<u64>().unwrap(),pid);let tid=t.parse::<u64>().unwrap();let cpu=f[1].trim_matches(['[',']']).parse::<u64>().unwrap();assert!(cpu<x["workers"].as_u64().unwrap());if tid!=pid{assert_eq!(allowed[&tid],cpu);}assert_eq!(f[3].parse::<u64>().unwrap(),16000000);count+=1;}assert_eq!(count,a["profiles"][name]["samples"].as_u64().unwrap());samples+=count;assert_eq!(read(r(format!("runs/loss-{name}/stdout.log")))["zero_lost"],true);let meta=fs::read_to_string(r(format!("runs/metadata-{name}/stdout.log"))).unwrap();assert!(meta.lines().any(|l|l.contains("PERF_RECORD_MMAP")&&l.contains(j["binary"].as_str().unwrap())&&l.contains(&format!("{pid}/{pid}"))));}
 let diagnostic=a["profiles"].as_object().unwrap().values().all(|v|v["qualified"]==true)&&a["counters"].as_object().unwrap().values().all(|v|v["qualified"]==true);assert_eq!(a["diagnostics_qualified"],diagnostic);let out=json!({"passed":true,"pin_occurrences":pins,"successful_commands":commands,"source_files":176,"originals_exact":175,"all_originals_recovered":true,"native_unfiltered_tests":126,"new_tests":1,"qualified_callers":rows.len(),"checked_query_invocations":queries,"reused_preflights":reused,"reconstructed_ratios_and_conditions":true,"exact_profile_pid_tid_cpu_period_MMAP_and_loss_review":true,"profile_samples":samples,"raw_PMU_not_independently_reparsed":true,"wrapper_explanatory":explanatory,"within_two_percent":equivalent,"production_changed":false,"new_proofs":0,"goal_achieved":false});fs::write(r("review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("{out}");}
